def build(start,stop):
 authored=[r for r in D if start<=r['ordinal']<stop];out=[]
 for judgement in authored:
  o=judgement['ordinal'];inp=INPUT[o];after=copy.deepcopy(inp['exact_5B_after'])
  for change in judgement['corrections']:
   parts=change['pointer'].strip('/').split('/');parent=after
   for k in parts[:-1]:parent=parent[int(k)] if isinstance(parent,list) else parent[k]
   key=int(parts[-1]) if isinstance(parent,list) else parts[-1];assert parent[key]==change['before'];parent[key]=change['after']
  facts=[]
  for component in judgement['components']:
   for qi,(p,qtext) in enumerate(component['quotes']):
    assert qtext in s.positive_string(after,p,realization_id='base'),(o,p,qtext)
    frow={k:copy.deepcopy(component[k]) for k in ['dimension','target','property','mode','value','requires']}
    frow.update(id=f'n{o}_{component["key"]}_{qi}',realization_id='base',pointer=p,quote=qtext)
    if component['mode']=='effect':frow.update(operation=component['operation'],receivers=component['receivers'])
    s._fact_valid(frow);facts.append(frow)
  paths=s.primary_paths(after,'base');units=[];uncovered=[]
  for p in sorted(paths):
   refs=[f['id'] for f in facts if f['pointer']==p]
   quote=s.positive_string(after,p,realization_id='base')
   if not refs and p not in judgement['explicit_nonsemantic_positive_paths']:uncovered.append(p)
